document.addEventListener('DOMContentLoaded', function() {
    // Elementos del DOM
    const calcularBtn = document.getElementById('calcular');
    const resetearBtn = document.getElementById('resetear');
    const numPuertasSelect = document.getElementById('num-puertas');
    const numVentanasSelect = document.getElementById('num-ventanas');
    const puertasContainer = document.getElementById('puertas-container');
    const ventanasContainer = document.getElementById('ventanas-container');
    const resultadosPanel = document.getElementById('resultados');
    
    // Variables para almacenar inputs
    let puertas = [];
    let ventanas = [];
    
    // Inicializar el simulador
    init();
    
    function init() {
        // Event listeners
        numPuertasSelect.addEventListener('change', updatePuertasInputs);
        numVentanasSelect.addEventListener('change', updateVentanasInputs);
        calcularBtn.addEventListener('click', calcular);
        resetearBtn.addEventListener('click', resetear);
        
        // Inicializar inputs
        updatePuertasInputs();
        updateVentanasInputs();
    }
    
    function updatePuertasInputs() {
        const numPuertas = parseInt(numPuertasSelect.value);
        puertasContainer.innerHTML = '';
        puertas = [];
        
        for (let i = 0; i < numPuertas; i++) {
            const puertaDiv = document.createElement('div');
            puertaDiv.className = 'door-window-inputs';
            puertaDiv.innerHTML = `
                <h4>Puerta ${i + 1}</h4>
                <div>
                    <label>Alto (m):</label>
                    <input type="number" id="alto-puerta-${i}" step="0.01" min="0.1" class="puerta-input">
                </div>
                <div>
                    <label>Ancho (m):</label>
                    <input type="number" id="ancho-puerta-${i}" step="0.01" min="0.1" class="puerta-input">
                </div>
            `;
            puertasContainer.appendChild(puertaDiv);
        }
    }
    
    function updateVentanasInputs() {
        const numVentanas = parseInt(numVentanasSelect.value);
        ventanasContainer.innerHTML = '';
        ventanas = [];
        
        for (let i = 0; i < numVentanas; i++) {
            const ventanaDiv = document.createElement('div');
            ventanaDiv.className = 'door-window-inputs';
            ventanaDiv.innerHTML = `
                <h4>Ventana ${i + 1}</h4>
                <div>
                    <label>Alto (m):</label>
                    <input type="number" id="alto-ventana-${i}" step="0.01" min="0.1" class="ventana-input">
                </div>
                <div>
                    <label>Ancho (m):</label>
                    <input type="number" id="ancho-ventana-${i}" step="0.01" min="0.1" class="ventana-input">
                </div>
            `;
            ventanasContainer.appendChild(ventanaDiv);
        }
    }
    
function calcular() {
    // Validar producto seleccionado
    const productoSelect = document.getElementById('producto');
    if (productoSelect.value === '') {
        alert('Por favor seleccione un producto');
        return;
    }
    
    // Obtener valores de los inputs
    const altoPared = parseFloat(document.getElementById('alto-pared').value);
    const anchoPared = parseFloat(document.getElementById('ancho-pared').value);
    
    // Validar dimensiones de la pared
    if (isNaN(altoPared) || isNaN(anchoPared) || altoPared <= 0 || anchoPared <= 0) {
        alert('Por favor ingrese dimensiones válidas para la pared');
        return;
    }
    
    // Calcular superficie total de la pared
    const superficiePared = altoPared * anchoPared;
    
    // Calcular superficie a restar (puertas)
    let superficiePuertas = 0;
    const inputsPuertas = document.querySelectorAll('.puerta-input');
    
    for (let i = 0; i < inputsPuertas.length; i += 2) {
        const alto = parseFloat(inputsPuertas[i].value);
        const ancho = parseFloat(inputsPuertas[i + 1].value);
        
        if (!isNaN(alto) && !isNaN(ancho) && alto > 0 && ancho > 0) {
            superficiePuertas += alto * ancho;
        }
    }
    
    // Calcular superficie a restar (ventanas)
    let superficieVentanas = 0;
    const inputsVentanas = document.querySelectorAll('.ventana-input');
    
    for (let i = 0; i < inputsVentanas.length; i += 2) {
        const alto = parseFloat(inputsVentanas[i].value);
        const ancho = parseFloat(inputsVentanas[i + 1].value);
        
        if (!isNaN(alto) && !isNaN(ancho) && alto > 0 && ancho > 0) {
            superficieVentanas += alto * ancho;
        }
    }
    
    // Validar que la superficie a restar no sea mayor que la superficie total
    const totalRestar = superficiePuertas + superficieVentanas;
    if (totalRestar >= superficiePared) {
        alert('Error: La superficie a restar (puertas + ventanas) es mayor o igual que la superficie total de la pared. Por favor revise las medidas.');
        return;
    }
    
    // Calcular superficie neta a pintar
    const superficieNeta = superficiePared - totalRestar;
    
    // Obtener rendimiento del producto seleccionado
    const rendimiento = parseFloat(productoSelect.selectedOptions[0].dataset.rendimiento);
    
    // Obtener factores de corrección
    const factorSuperficie = parseFloat(document.querySelector('input[name="superficie"]:checked').value);
    const factorTextura = parseFloat(document.querySelector('input[name="textura"]:checked').value);
    const factorTecnica = parseFloat(document.querySelector('input[name="tecnica"]:checked').value);
    
    // Calcular litros necesarios
    const litrosNecesarios = (superficieNeta / rendimiento) * factorSuperficie * factorTextura * factorTecnica;
    
    // Calcular cubetas y galones necesarios
    const CUBETA_LITROS = 19;
    const GALON_LITROS = 3.785;
    
    let cubetas = Math.floor(litrosNecesarios / CUBETA_LITROS);
    let resto = litrosNecesarios % CUBETA_LITROS;
    
    let galones = 0;
    if (resto > 0) {
        galones = Math.ceil(resto / GALON_LITROS);
        // Ajuste: si el sobrante es pequeño, considerar solo galones
        if (litrosNecesarios < CUBETA_LITROS) {
            cubetas = 0;
            galones = Math.ceil(litrosNecesarios / GALON_LITROS);
        }
    }
    
    // Calcular sobrante
    let sobranteLitros = (cubetas * CUBETA_LITROS + galones * GALON_LITROS) - litrosNecesarios;
    
    // Mostrar resultados
    document.getElementById('res-producto').textContent = productoSelect.selectedOptions[0].text;
    document.getElementById('res-superficie').textContent = `${superficieNeta.toFixed(2)} m²`;
    document.getElementById('res-litros').textContent = `${litrosNecesarios.toFixed(2)} litros`;
    document.getElementById('res-cubetas').textContent = `${cubetas} cubeta${cubetas !== 1 ? 's' : ''} (${cubetas * CUBETA_LITROS}L)`;
    document.getElementById('res-galones').textContent = `${galones} galón${galones !== 1 ? 'es' : ''} (${(galones * GALON_LITROS).toFixed(2)}L)`;
    document.getElementById('res-sobrante').textContent = `${sobranteLitros.toFixed(2)} litros`;
    
    // Mostrar panel de resultados (eliminar clase hidden)
    resultadosPanel.classList.remove('hidden');
    
    // Desplazamiento suave y enfoque al panel de resultados
    resultadosPanel.scrollIntoView({
        behavior: 'smooth',
        block: 'start'
    });
    
    // Hacer el panel enfocable para accesibilidad
    resultadosPanel.setAttribute('tabindex', '-1');
    resultadosPanel.focus();
    
    // Agregar borde o sombra para destacar el panel (opcional)
    resultadosPanel.style.boxShadow = '0 0 0 3px rgba(52, 152, 219, 0.3)';
    setTimeout(() => {
        resultadosPanel.style.boxShadow = '';
    }, 2000);
}
    
function resetear() {
    // Resetear formulario
    document.getElementById('producto').selectedIndex = 0;
    document.getElementById('alto-pared').value = '';
    document.getElementById('ancho-pared').value = '';
    document.getElementById('num-puertas').selectedIndex = 0;
    document.getElementById('num-ventanas').selectedIndex = 0;
    
    // Resetear opciones
    document.querySelector('input[name="superficie"][value="1.2"]').checked = true;
    document.querySelector('input[name="textura"][value="1.0"]').checked = true;
    document.querySelector('input[name="tecnica"][value="1.15"]').checked = true;
    
    // Limpiar contenedores
    puertasContainer.innerHTML = '';
    ventanasContainer.innerHTML = '';
    
    // Ocultar resultados
    resultadosPanel.classList.add('hidden');
    
    // Hacer focus en el panel-producto
    const panelProducto = document.querySelector('.panel-producto');
    panelProducto.scrollIntoView({
        behavior: 'smooth',
        block: 'start'
    });
    panelProducto.setAttribute('tabindex', '-1');
    panelProducto.focus();
    
    // Efecto visual temporal (opcional)
    panelProducto.style.boxShadow = '0 0 0 3px rgba(253, 78, 1, 0.3)';
    setTimeout(() => {
        panelProducto.style.boxShadow = '';
    }, 2000);
}
});